@rule("s0", "s1", otherwise="NotMentioned")
def confidentiality_agreement_exists():
    return "CONFIDENTIALITY AND NON-DISCLOSURE AGREEMENT GOVERNING THE INSPECTION OF STOCKHOLDER LIST" == "CONFIDENTIALITY AND NON-DISCLOSURE AGREEMENT GOVERNING THE INSPECTION OF STOCKHOLDER LIST"

@rule("s1", "s2", otherwise="NotMentioned")
def stockholder_demand():
    return "WHEREAS, on or about April 30, 2015, the Stockholder made a demand (the “Demand”) to inspect the stockholder list of the Company;" == "WHEREAS, on or about April 30, 2015, the Stockholder made a demand (the “Demand”) to inspect the stockholder list of the Company;"

@rule("s2", "s3", otherwise="NotMentioned")
def agreement_to_inspect():
    return "WHEREAS, pursuant to the Demand and subject to the Stockholder executing this Agreement, the Company has agreed to allow the Stockholder to inspect the stockholder list (which, together with information or analyses derived from information made available for inspection, is referred to as the “Confidential Material”);" == "WHEREAS, pursuant to the Demand and subject to the Stockholder executing this Agreement, the Company has agreed to allow the Stockholder to inspect the stockholder list (which, together with information or analyses derived from information made available for inspection, is referred to as the “Confidential Material”);"

@rule("s3", "s4", otherwise="NotMentioned")
def confidential_information():
    return "WHEREAS, the Company believes that stockholder list contains confidential information; IT IS HEREBY AGREED, by and between the Parties, this 30th day of April 2015, as follows:" == "WHEREAS, the Company believes that stockholder list contains confidential information; IT IS HEREBY AGREED, by and between the Parties, this 30th day of April 2015, as follows:"

@rule("s4", "s5", otherwise="NotMentioned")
def stockholder_use_confidential_material():
    return "1. Stockholder agrees that the Confidential Material is being produced to them only for purposes reasonably related to Stockholder’s interests as a stockholder of the Company and that Stockholder shall not utilize Confidential Material, any other information produced by the Company or anything derived from Confidential Material or derived from any other information produced by the Company for any other purpose." == "1. Stockholder agrees that the Confidential Material is being produced to them only for purposes reasonably related to Stockholder’s interests as a stockholder of the Company and that Stockholder shall not utilize Confidential Material, any other information produced by the Company or anything derived from Confidential Material or derived from any other information produced by the Company for any other purpose."

@rule("s5", "s6", otherwise="NotMentioned")
def stockholder_disclosure():
    return "2. The Stockholder will not disclose, publish, or communicate Confidential Material to any person or entity in any form (written, oral, electronic or through any other medium), either directly or indirectly, except as provided in this Confidentiality Agreement to end; provided that in no event shall stockholder, directly or indirectly, publically disclose, publish or communicate names, addresses, holdings of any other stockholder." == "2. The Stockholder will not disclose, publish, or communicate Confidential Material to any person or entity in any form (written, oral, electronic or through any other medium), either directly or indirectly, except as provided in this Confidentiality Agreement to end; provided that in no event shall stockholder, directly or indirectly, publically disclose, publish or communicate names, addresses, holdings of any other stockholder."

@rule("s6", "s7", otherwise="NotMentioned")
def disclosure_to_authorities():
    return "3. If the Stockholder is required (by interrogatory, subpoena, civil investigatory demand, or any similar process relating to any legal proceeding, investigation, hearing, or otherwise) to disclose in any manner any Confidential Material, the Stockholder will provide the Company with prompt notice (i.e., within 2 business days of receipt of such interrogatory, subpoena, demand, or any similar process), so that the Company may seek a protective order or other appropriate remedy and/or waive compliance with this Agreement in the event that such protective order or other remedy is not obtained, or if the Company waives compliance with the provisions of this Agreement, the Stockholder may furnish only such Confidential Material as they are advised is legally required and must exercise their best efforts to obtain assurance that confidential treatment will be accorded to any Confidential Material." == "3. If the Stockholder is required (by interrogatory, subpoena, civil investigatory demand, or any similar process relating to any legal proceeding, investigation, hearing, or otherwise) to disclose in any manner any Confidential Material, the Stockholder will provide the Company with prompt notice (i.e., within 2 business days of receipt of such interrogatory, subpoena, demand, or any similar process), so that the Company may seek a protective order or other appropriate remedy and/or waive compliance with this Agreement in the event that such protective order or other remedy is not obtained, or if the Company waives compliance with the provisions of this Agreement, the Stockholder may furnish only such Confidential Material as they are advised is legally required and must exercise their best efforts to obtain assurance that confidential treatment will be accorded to any Confidential Material."

@rule("s7", "s8", otherwise="NotMentioned")
def jurisdiction_delaware_chancery():
    return "4. Each Party who receives Confidential Material pursuant to this Agreement agrees to submit to the exclusive jurisdiction of the Delaware Court of Chancery in any action to enforce any provision of, or based on any right or claim arising out of, this Agreement including any action to determine any dispute as to the confidentiality of any information or document produced by the Company. Each Party hereby expressly waives any and all objections such Party may have to personal jurisdiction or to venue, including without limitation the inconvenience of such forum, in the Court of Chancery." == "4. Each Party who receives Confidential Material pursuant to this Agreement agrees to submit to the exclusive jurisdiction of the Delaware Court of Chancery in any action to enforce any provision of, or based on any right or claim arising out of, this Agreement including any action to determine any dispute as to the confidentiality of any information or document produced by the Company. Each Party hereby expressly waives any and all objections such Party may have to personal jurisdiction or to venue, including without limitation the inconvenience of such forum, in the Court of Chancery."

@rule("s8", "s9", otherwise="NotMentioned")
def irreparable_harm():
    return "5. Each Party agrees that the Company does not have an adequate remedy at law in the event of a breach of this Agreement by the Stockholder. The Parties further agree that, in the event of a breach of this Agreement by the Stockholder, the Company will suffer irreparable harm and will be entitled to specific performance and/or injunctive relief to enforce the terms of this Agreement. Such remedies shall not be deemed to be the exclusive remedies for any breach of this Agreement but shall be in addition to any other remedies to which the Company may be entitled at law or in equity." == "5. Each Party agrees that the Company does not have an adequate remedy at law in the event of a breach of this Agreement by the Stockholder. The Parties further agree that, in the event of a breach of this Agreement by the Stockholder, the Company will suffer irreparable harm and will be entitled to specific performance and/or injunctive relief to enforce the terms of this Agreement. Such remedies shall not be deemed to be the exclusive remedies for any breach of this Agreement but shall be in addition to any other remedies to which the Company may be entitled at law or in equity."

@rule("s9", "s10", otherwise="NotMentioned")
def amendment_change_waiver():
    return "6. This Agreement may not be amended, changed, waived, discharged, or terminated (except as explicitly provided herein), in whole or in part, except by an instrument in writing that refers specifically to this Agreement and that is signed by the Party against whom enforcement of such amendment, change, waiver, discharge, or termination is sought. The waiver by any Party of any breach of this Agreement will not be deemed or construed as a waiver of any other breach of this Agreement, whether prior, subsequent, or contemporaneous. No failure or delay in exercising any right, power, or privilege hereunder shall operate as a waiver thereof." == "6. This Agreement may not be amended, changed, waived, discharged, or terminated (except as explicitly provided herein), in whole or in part, except by an instrument in writing that refers specifically to this Agreement and that is signed by the Party against whom enforcement of such amendment, change, waiver, discharge, or termination is sought. The waiver by any Party of any breach of this Agreement will not be deemed or construed as a waiver of any other breach of this Agreement, whether prior, subsequent, or contemporaneous. No failure or delay in exercising any right, power, or privilege hereunder shall operate as a waiver thereof."

@rule("s10", "s11", otherwise="NotMentioned")
def binding_successors():
    return "7. This Agreement shall be binding upon and inure to the benefit of the Parties and their respective agents, executors, heirs, beneficiaries, successors, and assigns." == "7. This Agreement shall be binding upon and inure to the benefit of the Parties and their respective agents, executors, heirs, beneficiaries, successors, and assigns."

@rule("s11", "s12", otherwise="NotMentioned")
def governed_by_delaware_law():
    return "8. This Agreement shall be governed by and construed in accordance with the laws of the State of Delaware, without regard to its conflict of laws principles." == "8. This Agreement shall be governed by and construed in accordance with the laws of the State of Delaware, without regard to its conflict of laws principles."

@rule("s12", "s13", otherwise="NotMentioned")
def multiple_counterparts():
    return "9. This Agreement may be executed in multiple counterparts by any of the signatories hereto and as so executed shall constitute one agreement." == "9. This Agreement may be executed in multiple counterparts by any of the signatories hereto and as so executed shall constitute one agreement."

@rule("s13", "s14", otherwise="NotMentioned")
def entire_agreement():
    return "10. This Agreement constitutes the entire agreement between the Parties with regard to the subject matter hereof, and supersedes all prior agreements and understandings, written and oral, between the Parties with regard to the subject matter hereof." == "10. This Agreement constitutes the entire agreement between the Parties with regard to the subject matter hereof, and supersedes all prior agreements and understandings, written and oral, between the Parties with regard to the subject matter hereof."

@rule("s14", "s15", otherwise="NotMentioned")
def mutual_preparation():
    return "11. This Agreement will be deemed to have been mutually prepared by the Parties and will not be construed against either of them by reason of authorship." == "11. This Agreement will be deemed to have been mutually prepared by the Parties and will not be construed against either of them by reason of authorship."

@rule("s15", "s16", otherwise="NotMentioned")
def reverse_engineering():
    return "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information." == "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information."

query = "Entailment" if confidentiality_agreement_exists() and stockholder_demand() and agreement_to_inspect() and confidential_information() and stockholder_use_confidential_material() and stockholder_disclosure() and disclosure_to_authorities() and jurisdiction_delaware_chancery() and irreparable_harm() and amendment_change_waiver() and binding_successors() and governed_by_delaware_law() and multiple_counterparts() and entire_agreement() and mutual_preparation() and reverse_engineering() else "NotMentioned"
